import bpy, math
# --- material deepening ---
def set_color(mat_name, rgb, emit=None, strength=None):
    m=bpy.data.materials.get(mat_name)
    if not m: return
    bsdf=m.node_tree.nodes.get("Principled BSDF")
    bsdf.inputs["Base Color"].default_value=(*rgb,1)
    if emit:
        try:
            bsdf.inputs["Emission Color"].default_value=(*emit,1)
            bsdf.inputs["Emission Strength"].default_value=strength
        except: pass
set_color("Octopus",(0.82,0.20,0.12))
set_color("OctopusBelly",(0.98,0.55,0.38))
set_color("LanternRed",(0.78,0.07,0.04),emit=(0.9,0.08,0.02),strength=0.55)
