    if o:
        o.location.z=2.78
        o.dimensions.z=0.42
    d=get(f"NorenDot_{i}")
    if d: d.location.z=2.78
# lanterns: shrink and move to edges, raise
for i,x in enumerate([-2.75,2.75]):
    # delete centre lantern (index1)
    pass
for name in ["Lantern_1","LantCord_1","LantTop_1","LantBot_1","LantRib_1"]:
    o=get(name)
    if o: bpy.data.objects.remove(o, do_unlink=True)
for i, x in [(0,-2.75),(2,2.75)]:
