def add_text(name, text, loc, size, mat_name, extrude=0.02):
    mat=bpy.data.materials.get(mat_name)
    cu=bpy.data.curves.new(name,'FONT'); cu.body=text; cu.align_x='CENTER'; cu.align_y='CENTER'; cu.size=size; cu.extrude=extrude; cu.bevel_depth=0.004
    o=bpy.data.objects.new(name,cu); bpy.context.collection.objects.link(o); o.location=loc; o.rotation_euler=(math.radians(90),0,0)
    if mat: o.data.materials.append(mat)
    bpy.context.view_layer.objects.active=o; o.select_set(True); bpy.ops.object.convert(target='MESH')
    o=bpy.context.active_object; o.name=name; o.select_set(False); return o
